from __future__ import annotations

import base64
import hashlib
import zlib

_SOURCE_SHA256 = "c2ac303972a92d6bcb37a8c14dbd4784482fbf922f7d3067b3c6c3c6d0e3d381"
_SOURCE_ZLIB_BASE64 = ""

_source = zlib.decompress(base64.b64decode(_SOURCE_ZLIB_BASE64))
_actual = hashlib.sha256(_source).hexdigest()
if _actual != _SOURCE_SHA256:
    raise RuntimeError(
        f"embedded FF04 source hash mismatch: expected={_SOURCE_SHA256} actual={_actual}"
    )
exec(compile(_source, __file__, "exec"), globals(), globals())
